<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UInput from '@nuxt/ui/components/Input.vue';
import { state, workspaceAction, taskStatus } from '../store';
defineProps<{ disabled?: boolean }>();
defineEmits<{ newTask: [] }>();
const rename = ref(''), busy = ref(false), removing = ref(false), error = ref(''), filter = ref('');
const current = computed(() => state.sessions?.records.find(item => item.id === state.sessions?.selected));
const records = computed(() => state.sessions?.records.filter(item => !item.archived && item.title.toLowerCase().includes(filter.value.toLowerCase())).slice().reverse() ?? []);
watch(() => [current.value?.id, current.value?.title].join('|'), () => { rename.value = current.value?.title ?? ''; removing.value = false; }, { immediate: true });
async function action(body: unknown) { busy.value = true; error.value = ''; try { if (await workspaceAction('/api/sessions', body)) removing.value = false; else error.value = state.actionError || 'The task could not be updated. Your input is retained.'; } finally { busy.value = false; } }
</script>
<template><aside class="session-panel" aria-label="Tasks and sessions"><div class="rail-heading"><h2>Your tasks</h2><span class="muted">{{ state.sessions?.records.filter(item => !item.archived).length ?? 0 }}</span></div><UButton icon="i-lucide-plus" color="neutral" variant="outline" class="rail-new" :disabled="disabled || state.workspaceBusy" @click="$emit('newTask')">New task</UButton><label class="sr-only" for="task-filter">Find a task</label><UInput id="task-filter" v-model="filter" icon="i-lucide-search" placeholder="Find a task" class="w-full" /><nav class="task-rail-list" aria-label="Saved tasks"><button v-for="item in records" :key="item.id" class="task-rail-item" :class="{ selected: item.id === current?.id }" :aria-current="item.id === current?.id ? 'true' : undefined" :disabled="busy || disabled || state.workspaceBusy" @click="action({ action: 'select', id: item.id })"><strong>{{ item.title }}</strong><span><span class="task-phase" :class="item.status">{{ taskStatus(item.status) }}</span> · {{ item.provider.replace('-cli', '').replace('-api', '') }}</span></button><p v-if="!records.length" class="page-note">No tasks match your search.</p></nav><RouterLink class="rail-history" to="/history">View task history →</RouterLink><details v-if="current" class="task-settings"><summary>Task settings</summary><form class="settings-form" @submit.prevent="action({ action: 'rename', id: current?.id, title: rename })"><h3>Current task</h3><label for="rename-session">Name</label><UInput id="rename-session" v-model="rename" maxlength="120" required class="w-full" /><UButton type="submit" color="neutral" variant="outline" :loading="busy" :disabled="disabled || state.workspaceBusy">Rename</UButton><div class="actions"><UButton color="neutral" variant="ghost" :disabled="busy || disabled || state.workspaceBusy || current.busy" @click="action({ action: 'archive', id: current?.id })">Archive</UButton><UButton color="error" variant="ghost" :disabled="busy || disabled || state.workspaceBusy || current.busy" @click="removing = !removing">Delete</UButton></div><div v-if="removing" class="confirm-row"><p>Delete this task and all its saved messages?</p><UButton color="error" :loading="busy" :disabled="disabled || state.workspaceBusy" @click="action({ action: 'delete', id: current?.id })">Confirm deletion</UButton><UButton variant="ghost" color="neutral" @click="removing = false">Keep task</UButton></div></form></details><p v-if="error" class="error-text" role="alert">{{ error }}</p></aside></template>
